"""Render the draft scheme, assumptions and outstanding local design work."""
from pathlib import Path
from html import escape
import json, math
import pandas as pd
from scripts.check_concrete_candidate import build,OUT,COLORS
from src.geometry.naves_one import UPPER_YS

NAMES={'existing':'Исходный каркас','roof_runner':'Распорки у верхних поясов F',
'roof_plane':'Диагонали в плоскости кровли','lower_plane':'Диагонали у верхних поясов B',
'vertical_long':'Связи между двумя уровнями','vertical_cross':'Поперечные диафрагмы B',
'lower_tie':'Распорки нижних поясов B'}
model,added=build(True)
summary=pd.read_csv(OUT/'comparison.csv')
members=pd.read_csv(OUT/'proposed-members.csv')
checks=pd.read_csv(OUT/'conditional-member-checks.csv')

def plan(level):
    svg=['<svg viewBox="0 0 1000 790" role="img" aria-label="План расположения связей">']
    def point(n):
        a=model.nodes[n];return 70+70*a.x,735-70*a.y
    for e in model.elements:
        visible=(level=='roof' and ((e.role=='upper_chord' and 'top chord' in e.label) or e.group in ('roof_runner','roof_plane'))) or (level=='lower' and ((e.role=='lower_chord' and 'top chord' in e.label) or (e.role=='upper_chord' and 'bottom chord' in e.label) or e.group=='lower_plane'))
        if not visible:continue
        a,b=point(e.i),point(e.j);col=COLORS.get(e.group,'#b8bec6');w=3 if e.group in COLORS else 1.2
        svg.append(f'<line x1="{a[0]}" y1="{a[1]}" x2="{b[0]}" y2="{b[1]}" stroke="{col}" stroke-width="{w}"><title>{escape(e.label)}; {e.section}</title></line>')
    for row,y in enumerate(UPPER_YS):svg.append(f'<text x="5" y="{740-70*y}" font-size="15">F{row+1}</text>')
    for b,x in enumerate((0,2.588,6,9,12)):svg.append(f'<text x="{60+70*x}" y="768" font-size="17">B{b+1}</text>')
    svg.append('<text x="440" y="788" font-size="15">front · y = 0</text></svg>')
    return ''.join(svg)

def diaphragm():
    out=['<svg viewBox="0 0 1000 220" role="img" aria-label="Диафрагма между нижними фермами на y=3 м">']
    for e in added:
        if ':y3:' not in e.label:continue
        a,b=model.nodes[e.i],model.nodes[e.j]
        out.append(f'<line x1="{40+70*a.x}" y1="{180-150*(a.z-2.7)}" x2="{40+70*b.x}" y2="{180-150*(b.z-2.7)}" stroke="{COLORS[e.group]}" stroke-width="4"/>')
    out.append('<text x="40" y="25" font-size="16">Поперечная диафрагма y=3 м: верхний пояс B → соседний нижний пояс B</text><text x="40" y="215" font-size="15">Весь узел находится в высоте нижних ферм; соединения показаны по осям.</text></svg>')
    return ''.join(out)

forces=[]
for p in OUT.glob('draft_braced-*-joint-demands.csv'):
    if 'SLS' in p.name:continue
    d=pd.read_csv(p);d['case']=p.name.removeprefix('draft_braced-').removesuffix('-joint-demands.csv');forces.append(d)
f=pd.concat(forces,ignore_index=True);f['Mb_kNm']=(f.My_kNm**2+f.Mz_kNm**2)**.5
selected=[]
for label in ('B3 vertical 1','F3 vertical 20','K5'):
    g=f[f.label.eq(label)];selected.append(g.loc[g.Mb_kNm.idxmax()])
joints=pd.DataFrame(selected)[['label','case','node','end','section','N_kN','Vy_kN','Vz_kN','T_kNm','My_kNm','Mz_kNm']]
joints.to_csv(OUT/'joint-design-demands.csv',index=False)

# Independent deck-strip demand calculation; strength is not inferred from gross section.
q_uls=1.9*1.4+.45*1.2;q_sls=1.9+.45
roof=[]
for L in (1.,):
    roof.append(dict(span_m=L,q_uls_kPa=q_uls,M_kNm_per_m=q_uls*L*L/8,
        V_kN_per_m=q_uls*L/2,W_required_cm3_per_m=q_uls*L*L/8*1e6/230/1000,
        I_required_cm4_per_m=5*q_sls*(L*1000)**4/(384*200000*(L*1000/200))/10000))
roof=pd.DataFrame(roof);roof.to_csv(OUT/'deck-demand.csv',index=False)
# One 9.3 mm board carries all distributed load over a required <=250 mm gap.
t=9.3;L=250.;width=1000.;I=width*t**3/12;W=width*t*t/6
board_sigma=q_uls*L**2/8/W
board_defl=5*q_sls*L**4/(384*4500*I)

cols=['variant','case','Uz_mm','NM_245','NM_230','Rz_max_kN','mass_kg']
view=summary[summary.case.eq('UNIFORM')][cols].copy()
view.variant=view.variant.map({'existing':'Без новых связей','draft_braced':'Черновой вариант связей'})
view.columns=['Вариант','Снег','Uz расч., мм','N–M / 245','N–M / 230','Rz, кН','Металл, кг']
worst=checks.dropna(subset=['util_9_2_10']).sort_values('util_9_2_10',ascending=False).head(15)
counts=checks.status.value_counts().to_dict()
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Конкретный вариант навеса: связи, узлы, настил</title>
<style>body{font:17px/1.55 system-ui;max-width:1180px;margin:32px auto;padding:0 22px;color:#172537}h1{font-size:30px}h2{margin-top:36px}table{border-collapse:collapse;display:block;overflow:auto;font-size:14px}td,th{padding:8px;border:1px solid #c4ccd6;text-align:left}.note{background:#fff0d5;border-left:5px solid #b57500;padding:18px}svg{width:100%;background:#f8fafc;border:1px solid #ddd}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}@media(max-width:800px){.grid{grid-template-columns:1fr}}a{color:#005ca8}li{margin:9px 0}</style>
<h1>Конкретный вариант для дальнейшего проектирования</h1>
<p class="note"><b>Это расчётный черновик, не рабочий чертёж и не разрешение на изготовление.</b> Вариант отделён от основного пресета. Сечения и координаты новых труб заданы явно; их масса и жёсткость учтены. Новых неподвижных опор в пространстве нет. Раскрепления, соединения и настил пока имеют указанные ниже ограничения.</p>
<h2>Что предложено</h2>
<ul><li>Продольные распорки 60×40×3 между верхними поясами F на линиях B.</li><li>Диагонали 60×60×3 в двух горизонтальных уровнях: кровля и верхние пояса B. Полосы F1–F2, F5–F6, F8–F9, F9–F10; только там, где существуют обе соседние фермы B.</li><li>Диагонали между уровнями по линиям B: F1–F2, F3–F4, F5–F6, F7–F8, F9–F10.</li><li>Поперечные диафрагмы и распорки нижних поясов B на y=0, 3 и 6 м.</li><li>Кандидат кровли: Н75-750-0,7, сплошной слой ЦСП 2×10 мм, совместимый разделительный слой и мембрана. Это предложение состава, не подтверждение готовой системы конкретного производителя.</li></ul>
<p><a href="bracing-3d.html">Открыть вращаемую 3D-схему</a> · <a href="proposed-members.csv">Все новые трубы, узлы, длины и масса</a> · <a href="physical-model.json">Полная геометрия расчётного черновика</a></p>
<div class="grid"><section><h2>Уровень кровли</h2>'''+plan('roof')+'''<p>Бирюзовые — распорки; оранжевые — диагонали. Серые — существующие пояса F.</p></section><section><h2>Уровень верхних поясов B</h2>'''+plan('lower')+'''<p>Фиолетовые — диагонали между пересечениями B/F. Это физические трубы, а не фиксация координат узлов.</p></section></div>'''+diaphragm()
html+='''<h2>Результат сравнения</h2><p>Оба варианта посчитаны при одинаковой более тяжёлой кровле: нормативно 0,45 кПа ≈45,9 кг/м². Приняты коэффициенты: металл 1,05; кровля 1,20; снег 1,40. Нормативный снег 1,90 кПа. Расчёт линейный; коэффициенты постоянной нагрузки — явно заданные предпосылки для выбранного предварительного состава.</p>'''+view.to_html(index=False,float_format=lambda v:f'{v:.3f}')
html+=f'''<p><b>Добавлено {len(added)} стержней, {members.mass_kg.sum():.0f} кг металла.</b> Это тяжёлое решение, его нельзя выдавать за экономически оптимальный проект. Прежние 251,31 кг нерасставленных связей из исходной спецификации пока также оставлены как постоянная масса: они не объявлены заменёнными новыми трубами.</p>
<p>При нормативном равномерном снеге абсолютное Uz: исходный −16,77 мм, черновик −9,53 мм. Это абсолютные перемещения узлов, а не автоматически проверенный прогиб относительно опор. Пять снеговых схем: <a href="comparison.csv">все результаты</a>.</p>
<p>Первую попытку с диагоналями 40×40×3 отбраковали: одна из длинных диагоналей при длине 3,06 м и сжатии 23 кН превысила шарнирную оценку Эйлера (1,07). Новая попытка использует 60×60×3. Упругий множитель пространственной потери устойчивости новой идеальной модели — 9,21; это не запас по массе снега и не нормативное разрешение.</p>
<h2>Условная проверка сжатия с изгибом</h2>
<p>Проверены консервативные огибающие N, Mx, My по каждой группе стержней в каждой снеговой схеме по формулам (120)/(121) СП16. Максимумы могут находиться в разных сечениях одной группы, поэтому такая огибающая даёт запас. cx=cy=γc=1, Ry=245 МПа; φe ограничен снизу по несущей способности консервативной кривой центрального сжатия c. Таблица Д.3 переписана в диапазоне λ≤5,5 и mef≤20 без экстраполяции; малые λ и mef округлены до нижних границ таблицы в запас.</p>
<p><b>{counts.get('conditional_pass',0)} проверок условно удовлетворяют формуле; {counts.get('not_evaluated',0)} не оценены этим алгоритмом.</b> Это пары «группа–снеговая схема», не число уникальных физических стержней. Неоценённые случаи не объявлены проходящими. Для них нужно выбрать применимую проверку изгибаемого/растянуто-изгибаемого элемента и проверить местную устойчивость, срез и кручение.</p>
<p>Расчётные длины — предположения для предлагаемой схемы: B сверху около 1 м; B снизу по шагу новых диафрагм и опор; F — между пересечениями с B, консоль удвоена; новые связи и решётка — полная физическая длина; стойки — 2H. В обеих плоскостях взята большая длина. Требуется подтвердить жёсткость и прочность точек раскрепления, в том числе на условные поперечные силы. Таблица не заменяет эту проверку.</p>'''
html+=worst[['case','label','section','L_hypothesis_m','util_9_2_10']].to_html(index=False,float_format=lambda v:f'{v:.3f}')
html+='''<p><a href="conditional-member-checks.csv">Полная таблица с принятыми длинами и статусом каждой проверки</a>. Местная устойчивость всех стенок и работа стенок под сосредоточенными усилиями в этом черновике ещё не подтверждены.</p>
<h2>Узлы: что именно нужно проработать</h2>
<p>Ниже одновременные шесть усилий в выбранном сечении из одной снеговой схемы; момент и сила не смешаны из разных случаев. После добавления связей усилия изменились, поэтому прежние требования к сварке нельзя переносить автоматически.</p>'''+joints.to_html(index=False,float_format=lambda v:f'{v:.3f}')
html+='''<ul><li><b>B1 на K5:</b> опорное седло с распределительной плитой и боковыми рёбрами, передающее реакцию на боковые стенки трубы. Для первого эскиза можно рассматривать плиту 120×200×12 мм и боковые рёбра 6 мм; это стартовые размеры для местного расчёта, не согласованная деталь. Проверить контакт, изгиб плиты, стенки труб, передачу кручения и швы. Участок модели 0,52 мм в зоне опоры не моделирует эту местную работу.</li><li><b>B3 vertical 1 и F3 vertical 20:</b> рассмотреть парные боковые фасонки 6 мм с ориентировочным полем 120×160 мм вместо передачи всего момента только через торцевую обварку трубы. На эскизе нужно показать, как фасонки соединяют стенки стойки решётки со стенками пояса и обходят соседние раскосы. Толщина, длина швов и катет пока не назначены как проверенные.</li><li><b>B/F и новые связи:</b> задать накладки/фасонки с передачей продольной силы и моментов, проверить эксцентриситеты. В модели все новые узлы абсолютно жёсткие; эскиз без проверки этой предпосылки не закрывает расчёт.</li></ul>
<p>Простое указание «обварить по кругу» не задаёт несущую способность стенки пояса. Нужен местный расчёт по п.15.2.5 СП16 и разделу 14. Полные усилия сохранены в CSV для каждого снегового случая; <a href="joint-design-demands.csv">выбранные узлы</a>.</p>
<h2>Настил под мембраной: численные требования</h2>
<p>Направление гофр — поперёк F, опирание на соседние фермы F. Основной шаг F не больше 1 м. Для полосы шириной 1 м при разрезном опирании:</p>'''+roof.to_html(index=False,float_format=lambda v:f'{v:.4f}')
html+=f'''<p>W требуется для условного Ry=230 МПа; I — для E=200 ГПа и предварительного ограничения L/200. Для выбранного профнастила нужно подтвердить именно эффективные характеристики и местную несущую способность на опорах. В таблице производителя «Эталон» Н75-750-0,7 для пролёта 2 м указано 976 кг/м²; это предварительный ориентир, а не перенесённая на наш объект проверка: условия опирания и ограничения таблицы требуют подтверждения.</p>
<p>Оценка ЦСП: один слой минимальной толщиной 9,3 мм (10 мм минус допуск) несёт всю распределённую нагрузку при зазоре опирания не более 250 мм. Получено напряжение {board_sigma:.2f} МПа и мгновенный прогиб {board_defl:.2f} мм при E=4500 МПа. По данным ТАМАК паспортный предел изгиба для этой толщины — 12 МПа; он не подменяет расчётное сопротивление с учётом влажности и длительности. Совместная работа двух листов не учитывалась. Сосредоточенная монтажная нагрузка, стыки, крепления и длительный прогиб требуют проверки по выбранной кровельной системе.</p>
<p class="note"><b>Обнаружен край кровли, который нельзя пропустить:</b> последняя F10 стоит на y=8,696 м, край у K1-rear — y=9,659 м. Разница 0,963 м. Это не обычный межопорный пролёт 1 м. Требуется краевой прогон с передачей нагрузки на основные фермы либо отдельный расчёт консоли профнастила и её креплений, включая возможный отрыв опоры от снега на консоли. Краевой прогон пока не включён в этот черновик; его добавление требует перераспределить нагрузку кровли и повторить расчёт.</p>
<p>Снеговые нагрузки здесь — заданные равномерная и четыре частичные схемы. Возможный местный намёт от соседнего высокого дома отдельно не определён: известна близость дома к front, но численная высота и геометрия его кровли не заданы. Эти пять схем не объявлены исчерпывающим набором нормативных снеговых случаев.</p>
<h2>Статус передачи в работу</h2>
<p>Получены конкретная пространственная схема, перечень новых труб, сравнение, условные расчётные длины, нагрузки на настил и усилия для разработки узлов. Основной пресет не заменён. В текущем виде вариант <b>не готов к изготовлению</b>: остаются местные расчёты узлов/стенок, неохваченные проверки элементов, подтверждение жёсткости раскреплений и решение края кровли. Этот комплект можно передать конструктору для выпуска и проверки рабочих деталей.</p>
<p>Источники: <a href="https://nav.tn.ru/cloud/iblock/9f7/9f78782393359c071745ad3c74d9179f/SP-16.13330.2017-Stalnye-konstruktsii.pdf">СП16, изменения 1–6</a>; <a href="https://www.poetalon.ru/cat/profnastil-n75-750-0-7-mm/">таблица профнастила производителя</a>; <a href="https://csp.tamak.ru/uploads/2025/03/1742451966-brosura-csp-web.pdf">характеристики ЦСП ТАМАК</a>.</p></html>'''
(OUT/'report.html').write_text(html)
print('Saved',OUT/'report.html','CSP sigma',board_sigma,'deflection',board_defl)
